package com.asterion.foundry;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;
public final class MainActivity extends Activity {
 final int BG=0xff10141e,PANEL=0xff1b2432,INK=0xffeff5f7,MUTED=0xffa7b6c8,ACCENT=0xff83e5c6;
 Store store;LinearLayout body;TextView status;Spinner kind;EditText prompt,scale;String source="",page="Create",exportId;MeshView preview;Handler handler=new Handler();boolean visible;
 final String[] kinds={"Sword","Pavilion","Tree","Terrain","Image silhouette","Humanoid template","Quadruped template","OBJ geometry"};
 public void onCreate(Bundle b){super.onCreate(b);store=new Store(this);if(!ProductionService.active)store.recover();getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);show("Create");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},8);}
 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n);}
 TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(6),0,dp(6));return t;}
 void label(String v){body.addView(text(v,14,MUTED));}
 Button button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setTextColor(INK);b.setAllCaps(false);GradientDrawable d=new GradientDrawable();d.setColor(PANEL);d.setCornerRadius(dp(12));b.setBackground(d);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(0,dp(5),0,dp(5));body.addView(b,p);b.setOnClickListener(v->{try{action.run();}catch(Exception e){error(e);}});return b;}
 void show(String dest){if(preview!=null){preview.onPause();preview=null;}page=dest;LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(dp(18),dp(12),dp(18),dp(12));TextView title=text("ASTERION  /  FOUNDRY",14,ACCENT);root.addView(title);HorizontalScrollView nav=new HorizontalScrollView(this);LinearLayout row=new LinearLayout(this);for(String p:new String[]{"Create","Projects","Queue","Koikatsu","Performance"}){TextView tab=text(p,15,p.equals(dest)?ACCENT:MUTED);tab.setPadding(dp(10),dp(8),dp(10),dp(8));tab.setOnClickListener(v->show(p));row.addView(tab);}nav.addView(row);root.addView(nav);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);body.addView(text(dest,30,INK));try{switch(dest){case "Create":create();break;case "Projects":projects(false);break;case "Queue":projects(true);break;case "Koikatsu":kk();break;case "Performance":performance();break;}}catch(Exception e){error(e);}}
 void create(){label("Offline production · editable geometry · honest validation");prompt=new EditText(this);prompt.setTextColor(INK);prompt.setHintTextColor(MUTED);prompt.setHint("Describe an asset or name this project");body.addView(prompt);label("Available production methods");kind=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,kinds);kind.setAdapter(a);body.addView(kind);label("Sword, pavilion, tree and terrain are procedural recipes. Character/creature options create rig templates, not reconstructed appearances. Image mode extrudes a silhouette; it cannot infer the unseen back.");scale=new EditText(this);scale.setText("1.0");scale.setTextColor(INK);scale.setInputType(8194);body.addView(scale);label("Scale multiplier / image longest dimension in metres");button("Choose image or triangulated OBJ",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);});status=text(source.isEmpty()?"No reference selected":"Reference retained locally",13,MUTED);body.addView(status);button("Create",()->submit(false));button("Create with interruption checkpoint",()->submit(true));label("Original imports are preserved unchanged. Exported candidates remain visually unvalidated until reviewed.");}
 void submit(boolean pause){try{String k=(String)kind.getSelectedItem(),p=prompt.getText().toString().trim();String low=p.toLowerCase(Locale.ROOT);if(!low.isEmpty()&&kind.getSelectedItemPosition()==0){if(low.contains("tree"))k="Tree";else if(low.contains("terrain")||low.contains("landscape"))k="Terrain";else if(low.contains("pavilion"))k="Pavilion";else if(!low.contains("sword")&&!low.contains("blade")){new AlertDialog.Builder(this).setTitle("Description needs an unavailable engine").setMessage("This build cannot reconstruct arbitrary descriptions. Choose a supported recipe explicitly or supply a plain-background image for silhouette extrusion. Your description is retained.").setPositiveButton("OK",null).show();return;}}
  if((k.equals("Image silhouette")||k.equals("OBJ geometry"))&&source.isEmpty())throw new IllegalArgumentException("Choose a reference file first");float s=Float.parseFloat(scale.getText().toString());if(!Float.isFinite(s)||s<.01||s>100)throw new IllegalArgumentException("Scale must be 0.01–100");JSONObject q=new JSONObject().put("kind",k).put("description",p).put("scale",s).put("detail",12).put("source",source).put("pauseAfterGeometry",pause);store.enqueue(q);startQueue();show("Queue");}catch(Exception e){error(e);}}
 void startQueue(){try{startForegroundService(new Intent(this,ProductionService.class));}catch(Exception e){error(e);}}
 void projects(boolean queue)throws Exception{label(queue?"Stages reflect completed writes. Interrupted jobs keep their geometry checkpoints.":"Editable projects and export packages. Sources remain immutable.");if(queue){button("Run queued jobs",this::startQueue);button("Pause after current stage",()->{if(ProductionService.active)startService(new Intent(this,ProductionService.class).setAction("pause"));});}button("Refresh",()->show(page));ArrayList<JSONObject> jobs=store.jobs();if(jobs.isEmpty())label("No projects yet. Create an asset to begin.");for(JSONObject j:jobs){JSONObject q=new JSONObject(j.getString("request"));String id=j.getString("id"),state=j.getString("state");body.addView(text(q.getString("kind"),21,INK));label(state.toUpperCase(Locale.ROOT)+" · "+j.getString("message"));if(!q.optString("description").isEmpty())label(q.optString("description"));if(state.equals("paused")||state.equals("failed"))button("Resume "+id.substring(0,6),()->{store.state(id,"queued",j.optInt("stage"),"Resume requested");startQueue();show("Queue");});if(new File(store.project(id),"checkpoint.mesh").exists())button("Inspect asset",()->inspect(id));if(state.equals("complete")){button("Export editable package",()->{exportId=id;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,"Foundry-"+id.substring(0,8)+".zip");startActivityForResult(i,2);});button("Repeat using saved recipe",()->{try{store.enqueue(q);startQueue();show("Queue");}catch(Exception e){error(e);}});}label("────────────────────────");}}
 void inspect(String id){try{Mesh m=Mesh.load(new File(store.project(id),"checkpoint.mesh"));body.removeAllViews();body.addView(text("Inspect & refine",28,INK));preview=new MeshView(this,m);body.addView(preview,new LinearLayout.LayoutParams(-1,dp(330)));label("Drag to orbit · "+m.vertices.size()/3+" triangles · "+m.bones.size()+" bones");button("Front",()->preview.view(0,0));button("Side",()->preview.view(90,0));button("Back",()->preview.view(180,0));button("Top",()->preview.view(0,85));button("Refine recipe detail ×2",()->{try{JSONObject q=new JSONObject(store.job(id).getString("request"));int detail=q.getInt("detail");if(detail>=24){label("Recipe detail is already at the current budget limit.");return;}q.put("detail",Math.min(24,detail*2));q.put("pauseAfterGeometry",false);store.enqueue(q);startQueue();show("Queue");}catch(Exception e){error(e);}});File receipt=new File(store.project(id),"receipt.json");if(receipt.exists())label(java.nio.file.Files.readString(receipt.toPath()));button("Back to projects",()->show("Projects"));}catch(Exception e){error(e);}}
 void kk(){boolean installed;try{getPackageManager().getPackageInfo("com.asterion.kk.test",0);installed=true;}catch(Exception e){installed=false;}label(installed?"Existing Asterion KK installation detected and preserved.":"Existing KK package was not visible to this app.");label("Card preservation is available. Source-accurate mesh extraction, zipmod resolution and Android runtime IPC are NOT implemented. Cards contain parameters and dependency references; they are not self-contained geometry.");button("Preserve original character card",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/png");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,3);});label("No screenshot reconstruction is substituted for source data. No Windows plugin is executed by this app.");}
 void performance(){ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();getSystemService(ActivityManager.class).getMemoryInfo(m);PowerManager pm=getSystemService(PowerManager.class);label(String.format(Locale.ROOT,"Available RAM: %.2f GiB\nFree app storage: %.2f GiB\nThermal status: %d\nWorker: %s",m.availMem/1073741824.0,store.root.getUsableSpace()/1073741824.0,pm.getCurrentThermalStatus(),ProductionService.active?"running":"idle"));label("Geometry: Android CPU / ART\nPreview: OpenGL ES GPU rendering\nVulkan compute: not implemented\nQNN inference: not implemented\nAI reconstruction models: none loaded");label(store.memory());label("One worker · pause on severe thermal state, low RAM or low storage · immutable source cache · stage checkpoints. Android foreground-service time limits still apply. No control of other applications’ memory.");button("Refresh performance",()->show("Performance"));}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;Uri uri=data.getData();new Thread(()->{try{if(req==1||req==3){File tmp=new File(store.root,"sources/"+UUID.randomUUID()+".incoming");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(tmp)){byte[] buf=new byte[65536];long size=0;int n;while((n=in.read(buf))!=-1){size+=n;if(size>64L*1024*1024)throw new IOException("Current import limit is 64 MiB");out.write(buf,0,n);}}String hash=FilesUtil.hash(tmp);File target=new File(store.root,"sources/"+hash);if(target.exists())tmp.delete();else FilesUtil.move(tmp,target);source=target.getAbsolutePath();runOnUiThread(()->{if(req==1){if(status!=null)status.setText("Reference preserved · "+hash.substring(0,12));}else new AlertDialog.Builder(this).setTitle("Original card preserved").setMessage("SHA-256: "+hash+"\nGeometry extraction remains unavailable.").setPositiveButton("OK",null).show();});}else if(req==2){try(ZipOutputStream zip=new ZipOutputStream(getContentResolver().openOutputStream(uri))){File dir=store.project(exportId);for(String name:new String[]{"project.json","checkpoint.mesh","asset.glb","receipt.json","import-manifest.json"}){File f=new File(dir,name);if(!f.isFile())throw new IOException("Incomplete export: "+name);zip.putNextEntry(new ZipEntry(name));java.nio.file.Files.copy(f.toPath(),zip);zip.closeEntry();}JSONObject q=new JSONObject(store.job(exportId).getString("request"));if(!q.optString("source").isEmpty()){File f=new File(q.getString("source"));zip.putNextEntry(new ZipEntry("sources/"+FilesUtil.hash(f)));java.nio.file.Files.copy(f.toPath(),zip);zip.closeEntry();}}runOnUiThread(()->Toast.makeText(this,"Editable package exported",Toast.LENGTH_LONG).show());}}catch(Exception e){runOnUiThread(()->error(e));}}).start();}
 void error(Exception e){new AlertDialog.Builder(this).setTitle("Operation could not finish").setMessage(e.getMessage()==null?e.toString():e.getMessage()).setPositiveButton("OK",null).show();}
 @Override protected void onResume(){super.onResume();if(preview!=null)preview.onResume();}
 @Override protected void onPause(){if(preview!=null)preview.onPause();super.onPause();}
}
